"""Weather.gov (NWS) — MCP server generated by Handyman.

Tools for US weather data from the National Weather Service (weather.gov). Use get_active_alerts for current alerts/watches/warnings/advisories (including severe weather) covering a point or area. Use get_forecast/get_hourly_forecast for future conditions at a location. Use get_current_conditions for the latest observed conditions near a point. Use get_alert_details to fetch full text of a specific alert by its ID. All location-based tools accept latitude/longitude and internally resolve the NWS grid/zone/station, so you never need to know NWS internal IDs.

Source API: https://api.weather.gov/openapi.json
Regenerate with: handyman generate https://api.weather.gov/openapi.json
"""

import os
from typing import Annotated, Any

import httpx
from arcade_mcp_server import MCPApp
from arcade_mcp_server.exceptions import FatalToolError, NetworkTransportError, UpstreamError

app = MCPApp(
    name='weather_gov',
    version="0.1.0",
    log_level="ERROR",
    instructions='Tools for US weather data from the National Weather Service (weather.gov). Use get_active_alerts for current alerts/watches/warnings/advisories (including severe weather) covering a point or area. Use get_forecast/get_hourly_forecast for future conditions at a location. Use get_current_conditions for the latest observed conditions near a point. Use get_alert_details to fetch full text of a specific alert by its ID. All location-based tools accept latitude/longitude and internally resolve the NWS grid/zone/station, so you never need to know NWS internal IDs.',
)

BASE_URL = 'https://api.weather.gov'

# ---------------------------------------------------------------------------
# Request plumbing — the single HTTP door every tool goes through
# ---------------------------------------------------------------------------


def _request(
    method: str,
    path: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
) -> Any:
    """Issue one API request and return parsed JSON. Failures are raised as
    Arcade's typed tool errors — a plain exception would be masked as an
    "unhandled error" on the wire, hiding the message from the calling agent."""
    all_headers = dict(_DEFAULT_HEADERS)
    all_headers.update(headers or {})
    try:
        response = httpx.request(
            method,
            BASE_URL + path,
            params=params or None,
            headers=all_headers,
            timeout=30,
            follow_redirects=True,
        )
    except httpx.RequestError as error:
        raise NetworkTransportError(f"{method} {path} did not complete: {error}") from error
    if response.status_code >= 400:
        raise UpstreamError(
            f"{method} {path} failed ({response.status_code}): {response.text[:300]}",
            status_code=response.status_code,
        )
    try:
        return response.json()
    except ValueError as error:
        raise UpstreamError(
            f"{method} {path} returned non-JSON ({response.status_code})",
            status_code=response.status_code,
        ) from error


def _dig(payload: Any, path: str) -> Any:
    """Follow a dot path (numeric segments index lists) into a JSON payload,
    failing loudly when it is absent. Used between chained calls, where a
    missing value means the chain's wiring is wrong — an authoring defect, so
    it raises Arcade's fatal kind rather than an upstream one."""
    value = payload
    for key in path.split("."):
        if isinstance(value, list) and key.isdigit() and int(key) < len(value):
            value = value[int(key)]
        elif isinstance(value, dict) and key in value:
            value = value[key]
        else:
            found = sorted(value.keys()) if isinstance(value, dict) else (
                f"list of {len(value)}" if isinstance(value, list) else type(value).__name__)
            raise FatalToolError(f"response missing '{path}' (at '{key}'; found: {found})")
    return value


def _prune(payload: Any, path: str) -> Any:
    """Best-effort final shaping: return the payload at a dot path (numeric
    segments index lists), or the full payload when the shape drifted — a
    bigger answer beats a broken tool."""
    value = payload
    for key in path.split("."):
        if isinstance(value, list) and key.isdigit() and int(key) < len(value):
            value = value[int(key)]
        elif isinstance(value, dict) and key in value:
            value = value[key]
        else:
            return payload
    return value


def _as_object(value: Any) -> dict:
    """Tools always return a JSON object; non-object payloads are wrapped."""
    return value if isinstance(value, dict) else {"result": value}


# Identification values with safe defaults; override via environment. A
# secret with no default is omitted entirely until its variable is set —
# httpx rejects None header values.
_DEFAULT_HEADERS = {
    key: value
    for key, value in {
        'User-Agent': os.environ.get('WEATHER_GOV_USER_AGENT', 'weather-gov-mcp-server (contact@example.com)'),
    }.items()
    if value is not None
}


# ---------------------------------------------------------------------------
# Tools
# ---------------------------------------------------------------------------


@app.tool
def get_active_alerts(
    point: Annotated[str | None, "Latitude,longitude of the location to check, e.g. '36.1699,-115.1398'. Omit if using area instead."] = None,
    area: Annotated[str | None, "Comma-separated two-letter US state or marine area codes to check instead of a point, e.g. 'NV' or 'NV,CA'."] = None,
    severity: Annotated[str | None, "Comma-separated severity levels to filter by: Extreme, Severe, Moderate, Minor, Unknown. Set to 'Severe' when the user asks about 'severe weather'. Omit to include all severities."] = None,
    event: Annotated[str | None, "Comma-separated event names to filter by, e.g. 'Tornado Warning,Flood Warning'. Omit to include all event types."] = None,
    urgency: Annotated[str | None, 'Comma-separated urgency levels to filter by: Immediate, Expected, Future, Past, Unknown. Omit for all.'] = None,
) -> Annotated[dict, 'List of active alert features with properties (headline, severity, urgency, certainty, areaDesc, effective, expires, description, instruction).']:
    """
    Checks for currently active weather alerts, watches, warnings, and advisories
    (including severe weather, tornadoes, floods, winter storms, etc). Use this whenever
    a user asks 'are there any weather alerts/warnings' for a location, state, or the
    whole country — including questions specifically about 'severe weather'. To restrict
    to only severe-level alerts, pass severity='Severe'; leave severity unset to get
    alerts of all severities. Do NOT use for future/forecast conditions (use
    get_forecast instead). Returns a list of active alerts with headline, severity,
    urgency, certainty, area description, and effective/expiration times.
    """
    params: dict[str, Any] = {}
    if point is not None:
        params['point'] = point
    if area is not None:
        params['area'] = area
    if severity is not None:
        params['severity'] = severity
    if event is not None:
        params['event'] = event
    if urgency is not None:
        params['urgency'] = urgency
    response = _request("GET", '/alerts/active', params=params)
    return _as_object(_prune(response, 'features'))


@app.tool
def get_alert_details(
    alert_id: Annotated[str, "The full alert identifier/ID string, e.g. 'urn:oid:2.49.0.1.840.0...'."],
) -> Annotated[dict, 'Full alert object including area description, affected zones, sent/effective/onset/expires times, and instructions.']:
    """
    Fetches the full details of one specific weather alert given its alert ID (as
    returned in the 'id' field of get_active_alerts results). Use this only when you
    already have a specific alert ID and need its complete text; do not use it to search
    for alerts.
    """
    response = _request("GET", f"/alerts/{alert_id}")
    return _as_object(_prune(response, 'properties'))


@app.tool
def get_forecast(
    latitude: Annotated[float, 'Latitude of the location, decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location, decimal degrees.'],
    units: Annotated[str, "Unit system for the forecast text: 'us' for US customary or 'si' for metric. Defaults to 'us'."] = "us",
) -> Annotated[dict, 'List of forecast periods, each with name, temperature, wind, and a short forecast description.']:
    """
    Gets the multi-day textual weather forecast (e.g. 'Tonight', 'Monday', 'Monday
    Night') for a US latitude/longitude point. Use this for questions about upcoming
    weather over the next several days. For hour-by-hour detail, use get_hourly_forecast
    instead. For active alerts/warnings, use get_active_alerts instead.
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}")
    wfo = _dig(response_1, 'properties.gridId')
    grid_x = _dig(response_1, 'properties.gridX')
    grid_y = _dig(response_1, 'properties.gridY')
    params_2: dict[str, Any] = {}
    params_2['units'] = units
    response_2 = _request("GET", f"/gridpoints/{wfo}/{grid_x},{grid_y}/forecast", params=params_2)
    return _as_object(_prune(response_2, 'properties.periods'))


@app.tool
def get_hourly_forecast(
    latitude: Annotated[float, 'Latitude of the location, decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location, decimal degrees.'],
    units: Annotated[str, "Unit system for the forecast text: 'us' for US customary or 'si' for metric. Defaults to 'us'."] = "us",
) -> Annotated[dict, 'List of hourly forecast periods, each with start time, temperature, wind, and short forecast description.']:
    """
    Gets the hour-by-hour weather forecast for a US latitude/longitude point, covering
    the next several days in 1-hour increments. Use this when the user wants detailed
    near-term timing (e.g. 'will it rain this afternoon'). For multi-day summaries use
    get_forecast instead.
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}")
    wfo = _dig(response_1, 'properties.gridId')
    grid_x = _dig(response_1, 'properties.gridX')
    grid_y = _dig(response_1, 'properties.gridY')
    params_2: dict[str, Any] = {}
    params_2['units'] = units
    response_2 = _request("GET", f"/gridpoints/{wfo}/{grid_x},{grid_y}/forecast/hourly", params=params_2)
    return _as_object(_prune(response_2, 'properties.periods'))


@app.tool
def get_current_conditions(
    latitude: Annotated[float, 'Latitude of the location, decimal degrees.'],
    longitude: Annotated[float, 'Longitude of the location, decimal degrees.'],
) -> Annotated[dict, 'Latest observation for the nearest station: temperature, wind speed/direction, humidity, visibility, textDescription, and timestamp.']:
    """
    Gets the most recent observed weather conditions (temperature, wind, humidity, etc)
    from the nearest weather station to a US latitude/longitude point. Use this for
    'what is the weather right now' questions. Do NOT use this for future forecasts (use
    get_forecast) or for alerts (use get_active_alerts).
    """
    response_1 = _request("GET", f"/points/{latitude},{longitude}/stations")
    station_id = _dig(response_1, 'features.0.properties.stationIdentifier')
    response_2 = _request("GET", f"/stations/{station_id}/observations/latest")
    return _as_object(_prune(response_2, 'properties'))


if __name__ == "__main__":
    import sys

    app.run(transport=sys.argv[1] if len(sys.argv) > 1 else "stdio")
